import React, { useState } from 'react';
import { MeterGroup } from 'primereact/metergroup';
import { Card } from 'primereact/card';
import { Button } from 'primereact/button';

export default function Template() {
    const meter = (props, attr) => <span {...attr} key={props.index} style={{ background: `linear-gradient(to right, ${props.color1}, ${props.color2})`, width: props.percentage + '%' }} />;

    const labelList = ({ values }) => (
        <div className="uls-grid col-4">
            {values.map((item, index) => (
                <Card className="flex1" key={index}>
                    <div className="fxb fvc fsb gp5">
                        <div className="fxb fvc gp1">
                            <span className="fg-text-secondary font-size14">{item.label}</span>
                            <span className="bold-font font-size16">{item.value}%</span>
                        </div>
                        <span className="w28 h28 rds-circle fxb fvc fhc" style={{ backgroundColor: item.color1, color: '#ffffff' }}>
                            <i className={item.icon} />
                        </span>
                    </div>
                </Card>
            ))}
        </div>
    );

    const start = ({ totalPercent }) => (
        <div className="fxb fsb fvc gp3 relative mgt12 mgb3">
            <span>Storage</span>
            <span className="absolute text-right" style={{ width: totalPercent + '%' }}>
                {totalPercent}%
            </span>
            <span className="medium-font font-size14">1TB</span>
        </div>
    );

    const end = (
        <div className="fxb fhs fvc gp3 mgt10">
            <Button label="Manage Storage" outlined size="small" />
            <Button label="Update Plan" size="small" />
        </div>
    );

    const values = [
        { label: 'Apps', color1: '#34d399', color2: '#fbbf24', value: 25, icon: 'pi pi-table' },
        { label: 'Messages', color1: '#fbbf24', color2: '#60a5fa', value: 15, icon: 'pi pi-inbox' },
        { label: 'Media', color1: '#60a5fa', color2: '#c084fc', value: 20, icon: 'pi pi-image' },
        { label: 'System', color1: '#c084fc', color2: '#c084fc', value: 10, icon: 'pi pi-cog', meterTemplate: meter }
    ];

    return (
        <MeterGroup labelPosition="start" values={values} start={start} end={end} meter={meter} labelList={labelList} />
    )
}